<script setup>
import { createClient } from '@supabase/supabase-js'
const email = ref(''); const password = ref(''); const loading = ref(false); const message = ref(''); const error = ref(''); const config = useRuntimeConfig()
async function invitePlayer() { loading.value = true; message.value = ''; error.value = ''; try { const supabase = createClient(config.public.supabaseUrl, config.public.supabaseAnonKey); const { data } = await supabase.auth.getSession(); if (!data.session) throw new Error('Please sign in before inviting a player.'); await $fetch('/api/admin/invite', { method: 'POST', headers: { Authorization: `Bearer ${data.session.access_token}` }, body: { email: email.value, password: password.value } }); message.value = `Player account created for ${email.value}.`; email.value = ''; password.value = '' } catch (value) { error.value = value?.data?.statusMessage || value?.message || 'Unable to create the player.' } finally { loading.value = false } }
</script>
<template><div class="app-shell"><aside class="sidebar"><div class="brand"><div class="brand-mark"><span/><span/></div><div><strong>double<span>chance</span></strong><small>challenge tracker</small></div></div><div class="side-label">Workspace</div><nav class="main-nav"><NuxtLink class="nav-item" to="/">▦ <span>Overview</span></NuxtLink><NuxtLink class="nav-item active" to="/admin">♙ <span>Manage players</span></NuxtLink><NuxtLink class="nav-item" to="/challenges">⚙ <span>Manage challenges</span></NuxtLink><NuxtLink class="nav-item" to="/account">♙ <span>Account</span></NuxtLink></nav></aside><main class="account-page"><section class="auth-card admin-card"><p class="overline">CHALLENGE ADMIN</p><h1>Manage players</h1><p>Create a login for your friend and add them to this private challenge.</p><form @submit.prevent="invitePlayer"><label>Friend’s email address<input v-model="email" type="email" placeholder="friend@example.com" required/></label><label>Initial password<input v-model="password" type="password" minlength="6" placeholder="At least 6 characters" required/></label><button class="primary-button full-width" :disabled="loading">{{ loading ? 'Creating player…' : 'Add player →' }}</button><p v-if="message" class="auth-success">{{ message }}</p><p v-if="error" class="auth-error">{{ error }}</p></form><div class="admin-note"><strong>How it works</strong><span>Give your friend these credentials. They can log in immediately.</span></div></section></main></div></template>
